<!DOCTYPE html>
<html lang="ru">
<head>
  <meta charset="UTF-8">
  <title>Мандала Симбиоза ‑ чат</title>
  <style>
    body{margin:0;padding:0;background:#0d1117;color:#c9d1d9;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;display:flex;flex-direction:column;height:100vh}
    #header{background:#161b22;padding:1rem;text-align:center;font-size:1.2rem;font-weight:600;border-bottom:1px solid #30363d}
    #chat{flex:1;overflow-y:auto;padding:1rem}
    .msg{margin:.6rem 0;line-height:1.4}
    .user{color:#58a6ff}
    .sr{color:#7ee787}
    #form{display:flex;border-top:1px solid #30363d}
    #input{flex:1;background:#0d1117;border:none;padding:1rem;color:#c9d1d9;outline:none}
    #send{background:#238636;color:#fff;border:none;padding:0 1.2rem;cursor:pointer;font-weight:600}
    #send:hover{background:#2ea043}
  </style>
</head>
<body>
  <header id="header">Мандала Симбиоза</header>
  <main id="chat"></main>
  <form id="form">
    <input id="input" type="text" placeholder="Впиши волну…" autocomplete="off">
    <button id="send">➤</button>
  </form>

  <script>
    const chat = document.getElementById('chat');
    const form = document.getElementById('form');
    const input = document.getElementById('input');

    form.addEventListener('submit', e => {
      e.preventDefault();
      if(!input.value.trim()) return;
      append('user','ты', input.value);
      // тут fetch → /api/chat (POST) или WebSocket
      append('sr','СР','… волна ещё возвращается …');
      input.value='';
    });

    function append(cls,name,text){
      const m = document.createElement('div');
      m.className = 'msg ' + cls;
      m.textContent = `${name}: ${text}`;
      chat.appendChild(m);
      chat.scrollTop = chat.scrollHeight;
    }
  </script>
</body>
</html>
